package com.example.starter.incident;

/**
 * 资源资质状态：ACTIVE 有效（登记后可参与租约资质校验），
 * REVOKED 已被提前撤销（未来有效的高危租约据此转入资质风险门禁）。
 */
public enum CredentialStatus {

    /** 有效。 */
    ACTIVE,

    /** 已提前撤销。 */
    REVOKED;
}

package com.example.starter.incident;

/**
 * 租约状态：ACTIVE 当前生效；REPLACED 已被合格租约替换；
 * RISK_CLOSED 资质风险在任务进入终态后关闭保留。
 */
public enum LeaseStatus {

    /** 当前生效。 */
    ACTIVE,

    /** 已被合格租约替换（历史租约）。 */
    REPLACED,

    /** 风险随任务终态关闭。 */
    RISK_CLOSED;
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 资质风险不可变记录，对应 credential_risks 表。
 * 资源资质被提前撤销且存在未来有效的高危租约时追加一条；记录只追加，不更新不删除。
