 * CREDENTIAL_RISK 任务不得开始（只能先以合格资源替换租约）。
 */
@Transactional
public TaskView startTask(String incidentKey, String taskKey, String actor,
                          TaskActionRequest req) {
    String commandKey = requireText(req.commandKey(), "commandKey");
    leases.lockLeases();
